def _is_exact_run(target, container):
    # Test whether target is a straight contiguous line appearing as a complete
    # uninterrupted run in the other object's pixels.
    if len(target) < 2:
        return False
    rows = {}
    cols = {}
    for r, c in target:
        rows.setdefault(r, []).append(c)
        cols.setdefault(c, []).append(r)
    if len(rows) == 1:
        r = next(iter(rows)); cs = sorted(rows[r])
        if cs == list(range(cs[0], cs[0] + len(cs))):
            for y, x in container:
                if y == r and x == cs[0] - 1:
                    continue
            # normalize target at each possible location in the container
            for y, x in container:
                start = (y, x)
                run = {(y, x + i) for i in range(len(cs))}
                if run <= container and (y, x - 1) not in container and (y, x + len(cs)) not in container:
                    return True
    if len(cols) == 1:
        c = next(iter(cols)); rs = sorted(cols[c])
        if rs == list(range(rs[0], rs[0] + len(rs))):
            for y, x in container:
                run = {(y + i, x) for i in range(len(rs))}
                if run <= container and (y - 1, x) not in container and (y + len(rs), x) not in container:
                    return True
    return False

def transform(grid):
    out = [row[:] for row in grid]
    comps = _components(grid)
    candidates = []
    for color, cells in comps:
        if len(cells) < 2:
            continue
        for other_color, other in comps:
            if color == other_color or len(other) <= len(cells):
                continue
            if _is_exact_run(cells, other):
                candidates.append((len(cells), color, cells, other_color))
    if candidates:
        # Prefer the largest recognizable repeated sub-object.
        _, _, cells, new_color = max(candidates, key=lambda x: x[0])
        for r, c in cells:
            out[r][c] = new_color
    return out
